package com.ayanlabs.core.util;

import com.ayanlabs.core.entity.BaseEntity;

import java.util.UUID;

/**
 * Application-owned identifiers (not generated by Hibernate/JPA).
 * Replace {@link #newId()} to use ULIDs, time-ordered UUIDs, or external id services.
 */
public final class IdGenerator {

    private IdGenerator() {}

    public static UUID newId() {
        return UUID.randomUUID();
    }

    /** Sets {@link BaseEntity#setId} when null, typically right before the first persist. */
    public static void assignIfAbsent(BaseEntity entity) {
        if (entity != null && entity.getId() == null) {
            entity.setId(newId());
            entity.markNew();
        }
    }
}
